function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000000)) return 'Each value is a whole number from 1 to 10^6.';
  if (!Number.isInteger(k) || k < 1 || k > nums.length) return 'k is between 1 and nums.length.';
  let sum = 0;
  let max = 0;
  for (const v of nums) { sum += v; max = Math.max(max, v); }
  if (sum * max > Number.MAX_SAFE_INTEGER) return 'Keep sum(nums) * max(nums) at most 2^53 - 1 so the answer stays exact.';
  return null;
}

