function maxGcdSum(nums, k) {
  const gcd = (a, b) => {
    while (b !== 0) {
      const rest = a % b;
      a = b;
      b = rest;
    }
    return a;
  };
  const prefix = [0];
  for (const num of nums) {
    prefix.push(prefix[prefix.length - 1] + num);
  }
  let groups = [];
  let best = 0;

  for (let right = 0; right < nums.length; right++) {
    const next = [];
    for (const [g, start] of groups) {
      const merged = gcd(g, nums[right]);
      if (next.length === 0 || next[next.length - 1][0] !== merged) {
        next.push([merged, start]);
      }
    }
    if (next.length === 0 || next[next.length - 1][0] !== nums[right]) {
      next.push([nums[right], right]);
    }
    groups = next;
    for (const [g, start] of groups) {
      if (right - start + 1 >= k) {
        best = Math.max(best, g * (prefix[right + 1] - prefix[start]));
      }
    }
  }
  return best;
}

