function maxGcdSum(nums, k) {
  let best = 0;
  for (let i = 0; i < nums.length; i++) {
    let sum = 0;
    for (let j = i; j < nums.length; j++) {
      sum += nums[j];
      if (j - i + 1 < k) continue;
      let common = 0;
      for (let t = i; t <= j; t++) {
        let a = common, b = nums[t];
        while (b) [a, b] = [b, a % b];
        common = a;
      }
      best = Math.max(best, sum * common);
    }
  }
  return best;
}

