function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  if (size === 'large') {
    const n = int(1500, 2000);
    const mode = int(0, 2);
    const factor = [2, 6, 30, 210][int(0, 3)];
    const nums = Array.from({ length: n }, () => {
      if (mode === 0) return int(1, 1000000);
      if (mode === 1) return factor * int(1, Math.floor(1000000 / factor));
      return rand() < 0.8 ? factor * int(1, 50) : int(1, 1000);
    });
    return [nums, int(1, n)];
  }
  const n = int(1, 9);
  const factor = [1, 2, 3, 4, 6, 12][int(0, 5)];
  const nums = Array.from({ length: n }, () => {
    const roll = rand();
    if (roll < 0.6) return factor * int(1, 6);
    if (roll < 0.9) return int(1, 12);
    return 1000000 - int(0, 2) * 250000;
  });
  return [nums, int(1, n)];
}
